public static string Collide(Shape a, Shape b) => (a, b) switch
{
    (Circle c, Square s) => $"circle {c.Radius} vs square {s.Side}",
    (Square s, Circle c) => Collide(c, s),               // canonicalise symmetric pairs
    (Circle c1, Circle c2) => "two circles",
    (Square s1, Square s2) => "two squares",
    _ => throw new ArgumentException($"unhandled pair {a.GetType().Name}/{b.GetType().Name}"),
};

