public interface IShapeVisitor<T> {
    T Visit(Circle c);
    T Visit(Square s);
}
public abstract class Shape { public abstract T Accept<T>(IShapeVisitor<T> v); }
public sealed class Circle : Shape {
    public double Radius { get; init; }
    public override T Accept<T>(IShapeVisitor<T> v) => v.Visit(this);
}

public static string Collide(Shape a, Shape b) {
    dynamic x = a, y = b;          // binder resolves on the runtime types
    return CollideCore(x, y);
}

private static string CollideCore(Circle c, Square s) => "circle vs square";
private static string CollideCore(Circle c, Circle c2) => "two circles";
private static string CollideCore(Shape a, Shape b) =>
    throw new ArgumentException($"unhandled pair {a.GetType().Name}/{b.GetType().Name}");
